<?php
use App\Application\Customers\AttributionService;use App\Models\Partner;use App\Models\Party;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;
uses(RefreshDatabase::class);
test('origin lock is idempotent preserved on direct return and reassignment requires dispute',function(){$actor=User::factory()->create();$party=Party::create(['type'=>'PERSON','display_name'=>'Protected Client','legal_identity'=>[],'status'=>'ACTIVE']);$p1=Partner::create(['party_id'=>Party::create(['type'=>'ORGANIZATION','display_name'=>'Broker One','legal_identity'=>[],'status'=>'ACTIVE'])->id,'type'=>'BROKER','status'=>'ACTIVE','compliance'=>[]]);$p2=Partner::create(['party_id'=>Party::create(['type'=>'ORGANIZATION','display_name'=>'Broker Two','legal_identity'=>[],'status'=>'ACTIVE'])->id,'type'=>'BROKER','status'=>'ACTIVE','compliance'=>[]]);$service=app(AttributionService::class);$lock=$service->lock($party,$p1,'BROKER','ownership-v1','CRM import 001',$actor);expect($service->lock($party,$p1,'BROKER','ownership-v1','retry',$actor)->id)->toBe($lock->id)->and($service->lockOrPreserve($party,null,'SYSTEM','ownership-v1','public renewal',$actor)->partner_id)->toBe($p1->id);expect(fn()=>$service->lock($party,$p2,'BROKER','ownership-v1','takeover',$actor))->toThrow(ValidationException::class);$dispute=$service->openDispute($lock,$p2,'WRONG_ORIGIN','Broker transfer supported by signed records',['document'=>'doc-1'],$actor);$service->resolve($dispute,'REASSIGNED','Evidence reviewed and transfer approved',$actor,$p2);expect($lock->refresh()->partner_id)->toBe($p2->id);$this->assertDatabaseHas('attribution_events',['attribution_id'=>$lock->id,'type'=>'REASSIGNED','to_partner_id'=>$p2->id]);});
